# Let me try another common pattern: shift 7s down by 1 row
# This is a common gravity-like transformation in ARC

def shift_down_by_1(grid):
    """Shift all non-background cells down by 1 row"""
    rows = len(grid)
    cols = len(grid[0])
    output = [[0] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 7:
                # Wrap around: if r + 1 >= rows, put in row 0
                new_r = (r + 1) % rows
                output[new_r][c] = 7

    return output

